<x-layouts::app title="Cheque Settings"><div class="flex h-16 items-center justify-between border-b bg-white px-6"><div><h1 class="text-lg font-bold">Cheque Settings</h1><p class="text-xs text-slate-400">Reminders, automatic action and validation controls</p></div></div><div class="flex-1 overflow-y-auto bg-slate-50 p-6"><form method="POST" action="{{ route('cheques.settings.update') }}" class="mx-auto max-w-6xl space-y-5">@csrf @method('PUT') @if(session('success'))<div class="rounded-xl bg-emerald-50 p-4 text-xs text-emerald-700">{{ session('success') }}</div>@endif @foreach([['General',['cheque_enabled'=>'Enable Cheque Payments','cheque_received_enabled'=>'Enable Received Cheques','cheque_issued_enabled'=>'Enable Issued Cheques','cheque_require_attachment'=>'Require Attachment','cheque_allow_backdated'=>'Allow Backdated Cheques','cheque_allow_future'=>'Allow Future Cheques']],['Reminders',['cheque_reminders_enabled'=>'Enable Reminders','cheque_repeat_reminders'=>'Repeat Daily Until Resolved','cheque_dashboard_reminders'=>'Show Dashboard Reminder']],['Automatic Action',['cheque_auto_enabled'=>'Enable Automatic Action','cheque_auto_manager_approval'=>'Manager Approval Required']],['Returns',['cheque_require_return_reason'=>'Require Return Reason','cheque_add_return_charge_to_due'=>'Add Return Charge to Due','cheque_allow_replacement'=>'Allow Replacement']]] as $section)<section class="rounded-2xl border bg-white shadow-sm"><div class="border-b p-5"><h2 class="font-bold">{{ $section[0] }}</h2></div><div class="grid gap-4 p-5 sm:grid-cols-2 lg:grid-cols-3">@foreach($section[1] as $key=>$label)<label class="flex items-center gap-3 rounded-xl border p-4 text-xs font-bold"><input type="checkbox" name="{{ $key }}" value="1" @checked(($settings[$key]??'0')==='1')>{{ $label }}</label>@endforeach @if($section[0]==='Reminders')<label class="text-xs font-bold">Days Before Due<input type="number" name="cheque_reminder_days" value="{{ $settings['cheque_reminder_days']??3 }}" re